"""Finite state machine with guards and callbacks."""
from typing import Callable, Any, Optional


class StateMachine:
    def __init__(self, initial_state: str):
        self._state = initial_state
        # transitions[(state, event)] = {"target": state, "guard": callable|None}
        self._transitions: dict[tuple[str, str], dict] = {}
        # callbacks[("enter"|"exit", state)] = callable
        self._callbacks: dict[tuple[str, str], Callable] = {}

    def add_transition(
        self,
        source: str,
        event: str,
        target: str,
        guard: Optional[Callable[[], bool]] = None,
    ) -> None:
        """Register a transition. Optional guard must return True to allow it."""
        raise NotImplementedError

    def trigger(self, event: str, **context) -> bool:
        """Fire event. Returns True if transition happened, False if blocked/missing."""
        raise NotImplementedError

    def on_enter(self, state: str, callback: Callable) -> None:
        """Register callback called when entering state."""
        raise NotImplementedError

    def on_exit(self, state: str, callback: Callable) -> None:
        """Register callback called when leaving state."""
        raise NotImplementedError

    @property
    def current_state(self) -> str:
        return self._state
